const int PIN_Q0    = 2;  // D2
const int PIN_QM1   = 3;  // D3
const int PIN_START = 4;  // D4
const int PIN_LOAD  = 5;  // D5
const int PIN_SUB   = 6;  // D6
const int PIN_ALOAD = 7;  // D7
const int PIN_SHIFT = 8;  // B0
const int PIN_DONE  = 9;  // B1
const int PIN_LED   = 13; // B5

bool startAnterior = false;

void pulso(int pin) {
  digitalWrite(pin, HIGH);
  delayMicroseconds(5000);
  digitalWrite(pin, LOW);
  delayMicroseconds(5000);
}

void setup() {
  for (int p = 5; p <= 9; p++) {
    pinMode(p, OUTPUT);
    digitalWrite(p, LOW);
  }
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, HIGH); // Fijo en 5 V cuando está listo

  pinMode(PIN_Q0, INPUT);
  pinMode(PIN_QM1, INPUT);
  pinMode(PIN_START, INPUT);
}

void loop() {
  bool startActual = (digitalRead(PIN_START) == HIGH);

  // Detecta el momento exacto en que pasas START de 0 (gris) a 1 (verde)
  if (startActual && !startAnterior) {
    digitalWrite(PIN_LED, LOW);   // Apaga B5 mientras calcula
    digitalWrite(PIN_DONE, LOW);  // Apaga DONE al iniciar nuevo cálculo
    digitalWrite(PIN_SUB, LOW);

    pulso(PIN_LOAD);              // Carga M y Q, borra A y Q-1

    for (int i = 0; i < 4; i++) {
      int q0 = digitalRead(PIN_Q0);
      int qm = digitalRead(PIN_QM1);

      if (q0 == 0 && qm == 1) {
        digitalWrite(PIN_SUB, LOW);
        delayMicroseconds(2000);
        pulso(PIN_ALOAD);
      } else if (q0 == 1 && qm == 0) {
        digitalWrite(PIN_SUB, HIGH);
        delayMicroseconds(2000);
        pulso(PIN_ALOAD);
      }

      digitalWrite(PIN_SUB, LOW);
      pulso(PIN_SHIFT);
    }

    digitalWrite(PIN_DONE, HIGH); // Enciende DONE y lo deja fijo
    digitalWrite(PIN_LED, HIGH);  // Vuelve a encender B5
  }

  startAnterior = startActual;
  delayMicroseconds(1000);
}
